### Python

```python
import sys
import heapq

def main():
    data = sys.stdin.buffer.read().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    m = int(next(it))
    intervals = []
    for _ in range(m):
        x = int(next(it))
        y = int(next(it))
        L = x if x < y else y
        R = x if x > y else y
        intervals.append((L, R))

    # 按左端点升序排序
    intervals.sort(key=lambda seg: seg[0])

    pq = []          # 小根堆，存放右端点
    ans = 0
    idx = 0
    for i in range(1, n + 1):
        # 将所有 L <= i 的区间入堆
        while idx < m and intervals[idx][0] <= i:
            heapq.heappush(pq, intervals[idx][1])
            idx += 1
        # 移除右端点小于 i 的过期区间
        while pq and pq[0] < i:
            heapq.heappop(pq)
        # 匹配当前避难所
        if pq:
            heapq.heappop(pq)
            ans += 1

    sys.stdout.write(str(ans))

if __name__ == "__main__":
    main()
```

### Java

```java
import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;
        FastScanner(InputStream is) { in = is; }
        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }
        int nextInt() throws IOException {
            int c, sgn = 1, x = 0;
            do { c = read(); } while (c <= 32);
            if (c == '-') { sgn = -1; c = read(); }
            while (c > 32) {
                x = x * 10 + (c - '0');
                c = read();
            }
            return x * sgn;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int n = fs.nextInt();
        int m = fs.nextInt();
        int[][] segs = new int[m][2];
        for (int i = 0; i < m; i++) {
            int x = fs.nextInt();
            int y = fs.nextInt();
            segs[i][0] = Math.min(x, y);
            segs[i][1] = Math.max(x, y);
        }
        // 按左端点排序
        Arrays.sort(segs, (a, b) -> {
            if (a[0] != b[0]) return Integer.compare(a[0], b[0]);
            return Integer.compare(a[1], b[1]);
        });

        PriorityQueue<Integer> pq = new PriorityQueue<>(); // 小根堆存右端点
        int ans = 0;
        int idx = 0;
        for (int i = 1; i <= n; i++) {
            while (idx < m && segs[idx][0] <= i) {
                pq.offer(segs[idx][1]);
                idx++;
            }
            while (!pq.isEmpty() && pq.peek() < i) {
                pq.poll();
            }
            if (!pq.isEmpty()) {
                pq.poll();
                ans++;
            }
        }
        System.out.println(ans);
    }
}
