### C++

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    if (!(cin >> n >> m)) return 0;
    vector<pair<int, int>> intervals;
    intervals.reserve(m);
    for (int i = 0; i < m; ++i) {
        int x, y;
        cin >> x >> y;
        int L = min(x, y);
        int R = max(x, y);
        intervals.emplace_back(L, R);
    }
    // 按左端点排序
    sort(intervals.begin(), intervals.end(),
         [](const auto& a, const auto& b) {
             if (a.first != b.first) return a.first < b.first;
             return a.second < b.second;
         });

    priority_queue<int, vector<int>, greater<int>> pq; // 小根堆存右端点
    int ans = 0, idx = 0;
    for (int i = 1; i <= n; ++i) {
        // 加入所有左端点 <= i 的区间
        while (idx < m && intervals[idx].first <= i) {
            pq.push(intervals[idx].second);
            ++idx;
        }
        // 移除过期的区间
        while (!pq.empty() && pq.top() < i) {
            pq.pop();
        }
        // 用当前避难所匹配右端点最小的区间
        if (!pq.empty()) {
            pq.pop();
            ++ans;
        }
    }
    cout << ans << '\n';
    return 0;
}
